let data=JSON.parse(localStorage.getItem(KEY)||'null')||seed;data.stages=data.stages?.length?data.stages:seed.stages;data.modules??=[];data.tasks??=[];data.candidates??=[];data.contacts??=[];data.training??[];let activeDay='全部',activeRole='全部',currentView='overview';
const $=s=>document.querySelector(s), uid=p=>p+Date.now().toString(36), esc=x=>String(x??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m])), toast=t=>{const e=$('#toast');e.textContent=t;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),1400)}, save=()=>{localStorage.setItem(KEY,JSON.stringify(data));toast('已自动保存')};
