function switchView(v){currentView=v;document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===v));document.querySelectorAll('.view').forEach(e=>e.classList.toggle('active',e.id==='view-'+v));const t=titles[v];$('#pageKicker').textContent=t[0];$('#pageTitle').innerHTML=t[1]+' <span>✦</span>';$('#pageDescription').textContent=t[2];}
function render(){renderStats();renderModules();renderLinks();renderTasks();renderKanban();renderContacts();renderTraining();switchView(currentView)}
function renderStats(){const done=data.tasks.filter(t=>t.done).length,total=data.tasks.length,tp=data.training.reduce((a,r)=>a+Number(r.people),0),tc=data.training.reduce((a,r)=>a+Number(r.completed),0);$('#heroProgress').textContent=Math.round(done/Math.max(total,1)*100)+'%';$('#stats').innerHTML=[['本周任务',`${done}/${total}`,'已完成任务','✓','violet'],['候选人',data.candidates.length,'在招岗位候选人','◎','green'],['培训场次',data.training.length,'本周已记录','▤','orange'],['平均完成率',`${tp?Math.round(tc/tp*100):0}%`,'培训参与完成率','↗','pink']].map(x=>`<div class="stat-card"><div class="stat-label">${x[2]}<span class="stat-icon ${x[4]}">${x[3]}</span></div><div class="stat-value">${x[1]}</div><div class="stat-note">${x[0]}</div></div>`).join('')}
function renderModules(){const g=$('#moduleGrid');if(!g)return;g.innerHTML=data.modules.map(m=>`<article class="module-card" draggable="true" data-id="${m.id}"><div class="module-top"><div class="module-title"><div class="module-icon ${m.tone}">${esc(m.icon)}</div><div><h3>${esc(m.title)}</h3><small>${m.links.length} 个快捷入口</small></div></div><div class="module-actions"><button class="mini-btn edit-module" data-id="${m.id}">✎</button><button class="mini-btn delete-module" data-id="${m.id}">×</button></div></div><p class="module-desc">${esc(m.desc)}</p><div class="link-chips">${m.links.map(l=>`<span class="link-chip" data-url="${esc(l.url)}">${esc(l.title)}</span>`).join('')}</div><span class="drag-handle">⋮⋮</span></article>`).join('')||'<div class="empty">还没有模块，点击右上角新增一个吧</div>';g.querySelectorAll('.link-chip').forEach(e=>e.onclick=()=>openUrl(e.dataset.url));g.querySelectorAll('.delete-module').forEach(b=>b.onclick=()=>{if(confirm('确定删除这个模块吗？')){data.modules=data.modules.filter(m=>m.id!==b.dataset.id);save();render()}});g.querySelectorAll('.edit-module').forEach(b=>b.onclick=()=>openModal('module',data.modules.find(m=>m.id===b.dataset.id)));setupDrag()}
function openUrl(url){if(url&&url!=='#')window.open(url,'_blank');else toast('这是一个待补充的入口')}
function setupDrag(){let drag;document.querySelectorAll('.module-card').forEach(c=>{c.ondragstart=()=>{drag=c;c.classList.add('dragging')};c.ondragend=()=>c.classList.remove('dragging');c.ondragover=e=>e.preventDefault();c.ondrop=()=>{if(drag&&drag!==c){const a=[...document.querySelectorAll('.module-card')],[from,to]=[a.indexOf(drag),a.indexOf(c)];const [x]=data.modules.splice(from,1);data.modules.splice(to,0,x);save();render()}}})}
function renderLinks(){const e=$('#quickLinks');if(!e)return;const links=data.modules.flatMap(m=>m.links.map((l,i)=>({...l,module:m.title,moduleId:m.id,index:i})));e.innerHTML=links.length?links.map(l=>`<div class="quick-link"><div class="quick-link-main" data-url="${esc(l.url)}"><div class="quick-link-icon">↗</div><div><div class="quick-link-title">${esc(l.title)}</div><div class="quick-link-url">${esc(l.url||'待补充链接')} · ${esc(l.module)}</div></div></div><div class="row-actions"><button class="mini-btn open-link" data-url="${esc(l.url)}">打开</button><button class="mini-btn edit-link" data-module="${l.moduleId}" data-index="${l.index}">✎</button><button class="mini-btn delete-link" data-module="${l.moduleId}" data-index="${l.index}">×</button></div></div>`).join(''):'<div class="empty">暂无快捷入口，点击右上角“导入链接”开始添加。</div>';e.querySelectorAll('.open-link,.quick-link-main').forEach(b=>b.onclick=()=>openUrl(b.dataset.url));e.querySelectorAll('.delete-link').forEach(b=>b.onclick=()=>{const m=data.modules.find(x=>x.id===b.dataset.module);m.links.splice(+b.dataset.index,1);save();render()});e.querySelectorAll('.edit-link').forEach(b=>b.onclick=()=>{const m=data.modules.find(x=>x.id===b.dataset.module);openModal('link',{...m.links[+b.dataset.index],moduleId:m.id,index:+b.dataset.index})})}
function renderTasks(){const tabs=['全部','周一','周二','周三','周四','周五'];$('#weekTabs').innerHTML=tabs.map(d=>`<button class="day-tab ${activeDay===d?'active':''}" data-day="${d}">${d}</button>`).join('');$('#weekTabs').querySelectorAll('button').forEach(b=>b.onclick=()=>{activeDay=b.dataset.day;renderTasks()});const list=data.tasks.filter(t=>activeDay==='全部'||t.day===activeDay);$('#taskList').innerHTML=list.length?list.map(t=>`<div class="task-item ${t.done?'done':''}"><button class="check" data-id="${t.id}">${t.done?'✓':''}</button><div><div class="task-name">${esc(t.name)}</div><div class="task-note">${esc(t.note||'暂无备注')}</div></div><span class="task-owner">${esc(t.owner||'未分配')}</span><div class="row-actions"><button class="mini-btn edit-task" data-id="${t.id}">✎</button><button class="mini-btn delete-task" data-id="${t.id}">×</button></div></div>`).join(''):'<div class="empty">这一天暂时没有任务</div>';$('#taskList').querySelectorAll('.check').forEach(b=>b.onclick=()=>{data.tasks.find(x=>x.id===b.dataset.id).done=!data.tasks.find(x=>x.id===b.dataset.id).done;save();render()});$('#taskList').querySelectorAll('.delete-task').forEach(b=>b.onclick=()=>{data.tasks=data.tasks.filter(x=>x.id!==b.dataset.id);save();render()});$('#taskList').querySelectorAll('.edit-task').forEach(b=>b.onclick=()=>openModal('task',data.tasks.find(x=>x.id===b.dataset.id)))}
function renderKanban(){const roles=['全部',...new Set(data.candidates.map(c=>c.role))];$('#positionFilters').innerHTML=roles.map(r=>`<button class="filter-btn ${activeRole===r?'active':''}" data-role="${esc(r)}">${esc(r)}</button>`).join('');$('#positionFilters').querySelectorAll('button').forEach(b=>b.onclick=()=>{activeRole=b.dataset.role;renderKanban()});$('#kanban').innerHTML=data.stages.map(s=>{const cs=data.candidates.filter(c=>(activeRole==='全部'||c.role===activeRole)&&c.stage===s);return `<div class="kanban-col"><div class="col-head"><span>${esc(s)}</span><span class="count">${cs.length}</span></div>${cs.map(c=>`<div class="candidate-card"><div class="candidate-main" data-id="${c.id}"><strong>${esc(c.name)}</strong><span>${esc(c.role)}</span><span class="tag">${esc(s)}</span></div><div class="row-actions"><button class="mini-btn edit-candidate" data-id="${c.id}">✎</button><button class="mini-btn delete-candidate" data-id="${c.id}">×</button></div></div>`).join('')||'<div class="empty">暂无</div>'}</div>`}).join('');$('#kanban').querySelectorAll('.edit-candidate,.candidate-main').forEach(b=>b.onclick=()=>openModal('candidate',data.candidates.find(c=>c.id===b.dataset.id)));$('#kanban').querySelectorAll('.delete-candidate').forEach(b=>b.onclick=()=>{data.candidates=data.candidates.filter(c=>c.id!==b.dataset.id);save();render()})}
function renderContacts(){$('#contactsList').innerHTML=data.contacts.length?data.contacts.map(c=>`<div class="contact-row"><div class="contact-main"><div class="contact-avatar">${esc(c.name.slice(0,1))}</div><div><div class="contact-name">${esc(c.name)}</div><div class="contact-role">${esc(c.role)} · ${esc(c.info)}</div></div></div><div class="row-actions"><button class="copy-btn" data-info="${esc(c.info)}">⧉</button><button class="mini-btn edit-contact" data-id="${c.id}">✎</button><button class="mini-btn delete-contact" data-id="${c.id}">×</button></div></div>`).join(''):'<div class="empty">暂无联系人</div>';$('#contactsList').querySelectorAll('.copy-btn').forEach(b=>b.onclick=()=>{navigator.clipboard?.writeText(b.dataset.info);toast('备注已复制')});$('#contactsList').querySelectorAll('.delete-contact').forEach(b=>b.onclick=()=>{data.contacts=data.contacts.filter(c=>c.id!==b.dataset.id);save();render()});$('#contactsList').querySelectorAll('.edit-contact').forEach(b=>b.onclick=()=>openModal('contact',data.contacts.find(c=>c.id===b.dataset.id)))}
function renderTraining(){const tp=data.training.reduce((a,r)=>a+Number(r.people),0),tc=data.training.reduce((a,r)=>a+Number(r.completed),0);$('#trainingSummary').innerHTML=`<div class="summary-item"><span>累计参与人次</span><strong>${tp}</strong></div><div class="summary-item"><span>累计完成人次</span><strong>${tc}</strong></div><div class="summary-item"><span>整体完成率</span><strong class="rate">${tp?Math.round(tc/tp*100):0}%</strong></div>`;$('#trainingTable').innerHTML=data.training.map(r=>`<tr><td>${esc(r.topic)}</td><td>${esc(r.date)}</td><td>${r.people}</td><td>${r.completed}</td><td class="rate">${Math.round(r.completed/r.people*100)}%</td><td><button class="mini-btn edit-training" data-id="${r.id}">✎</button><button class="delete-link" data-id="${r.id}">×</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">暂无培训数据</td></tr>';$('#trainingTable').querySelectorAll('.delete-link').forEach(b=>b.onclick=()=>{data.training=data.training.filter(r=>r.id!==b.dataset.id);save();render()});$('#trainingTable').querySelectorAll('.edit-training').forEach(b=>b.onclick=()=>openModal('training',data.training.find(r=>r.id===b.dataset.id)))}
const modal=$('#modal');function openModal(type,item){modal.classList.add('open');modal.dataset.type=type;modal.dataset.id=item?.id||'';modal.dataset.index=item?.index??'';$('#modalTitle').textContent=(item?'编辑':'新增')+({module:'模块',link:'快捷入口',task:'任务',candidate:'候选人',contact:'联系人',training:'培训数据',stage:'招聘阶段'}[type]);const f=$('#modalFields'),v=k=>esc(item?.[k]);if(type==='module')f.innerHTML=`<div class="field"><label>模块名称</label><input name="title" required value="${v('title')}" /></div><div class="field"><label>一句话描述</label><textarea name="desc">${v('desc')}</textarea></div><div class="field-row"><div class="field"><label>图标</label><input name="icon" value="${v('icon')||'✦'}" /></div><div class="field"><label>颜色</label><select name="tone"><option value="violet">紫色</option><option value="green">绿色</option><option value="orange">橙色</option><option value="pink">粉色</option></select></div></div>`;else if(type==='link')f.innerHTML=`<div class="field"><label>入口名称</label><input name="title" required value="${v('title')}" /></div><div class="field"><label>链接地址（可粘贴飞书 / 表格 / 文档 URL）</label><input name="url" required placeholder="https://" value="${v('url')}" /></div><div class="field"><label>归属模块</label><select name="moduleId">${data.modules.map(m=>`<option value="${m.id}" ${m.id===item?.moduleId?'selected':''}>${esc(m.title)}</option>`).join('')}</select></div>`;else if(type==='task')f.innerHTML=`<div class="field"><label>任务名称</label><input name="name" required value="${v('name')}" /></div><div class="field-row"><div class="field"><label>安排日期</label><select name="day">${['周一','周二','周三','周四','周五'].map(d=>`<option ${d===item?.day?'selected':''}>${d}</option>`).join('')}</select></div><div class="field"><label>负责人</label><input name="owner" value="${v('owner')||'我'}" /></div></div><div class="field"><label>进度备注</label><textarea name="note">${v('note')}</textarea></div>`;else if(type==='candidate')f.innerHTML=`<div class="field"><label>候选人姓名</label><input name="name" required value="${v('name')}" /></div><div class="field"><label>应聘岗位</label><input name="role" required value="${v('role')}" /></div><div class="field"><label>当前阶段（可在招聘看板中自定义）</label><select name="stage">${data.stages.map(s=>`<option ${s===item?.stage?'selected':''}>${esc(s)}</option>`).join('')}</select></div>`;else if(type==='contact')f.innerHTML=`<div class="field"><label>姓名 / 群聊名称</label><input name="name" required value="${v('name')}" /></div><div class="field"><label>角色</label><input name="role" value="${v('role')}" /></div><div class="field"><label>备注（可复制）</label><input name="info" value="${v('info')}" /></div>`;else if(type==='training')f.innerHTML=`<div class="field"><label>培训主题</label><input name="topic" required value="${v('topic')}" /></div><div class="field-row"><div class="field"><label>日期</label><input type="date" name="date" required value="${v('date')}" /></div><div class="field"><label>参与人数</label><input type="number" name="people" min="1" required value="${v('people')}" /></div></div><div class="field"><label>完成人数</label><input type="number" name="completed" min="0" required value="${v('completed')}" /></div>`;else if(type==='stage')f.innerHTML=`<div class="field"><label>阶段名称</label><input name="name" required placeholder="例如：待发 Offer" /></div>`}
$('#modalForm').onsubmit=e=>{e.preventDefault();const type=modal.dataset.type,id=modal.dataset.id,fd=new FormData(e.target),o=Object.fromEntries(fd.entries());if(type==='module'){if(id)Object.assign(data.modules.find(x=>x.id===id),o);else data.modules.push({...o,id:uid('m'),links:[]})}else if(type==='link'){const target=data.modules.find(m=>m.id===o.moduleId)||data.modules[0];if(target){const clean={title:o.title,url:o.url||'#'};if(id){const old=data.modules.find(m=>m.id===item?.moduleId);old.links[+modal.dataset.index]=clean}else target.links.push(clean)}}else if(type==='task'){if(id)Object.assign(data.tasks.find(x=>x.id===id),o);else data.tasks.push({...o,id:uid('t'),done:false})}else if(type==='candidate'){if(id)Object.assign(data.candidates.find(x=>x.id===id),o);else data.candidates.push({...o,id:uid('c')})}else if(type==='contact'){if(id)Object.assign(data.contacts.find(x=>x.id===id),o);else data.contacts.push({...o,id:uid('p')})}else if(type==='training'){const clean={...o,people:+o.people,completed:+o.completed};if(id)Object.assign(data.training.find(x=>x.id===id),clean);else data.training.push({...clean,id:uid('r')})}else if(type==='stage'){data.stages.push(o.name)}modal.classList.remove('open');save();render()};
document.querySelectorAll('.nav-item').forEach(b=>b.onclick=()=>switchView(b.dataset.view));$('#addModuleBtn').onclick=()=>openModal('module');$('#addLinkBtn').onclick=()=>openModal('link');$('#importLinkBtn').onclick=()=>openModal('link');$('#addTaskBtn').onclick=()=>openModal('task');$('#addCandidateBtn').onclick=()=>openModal('candidate');$('#manageStageBtn').onclick=()=>openModal('stage');$('#addContactBtn').onclick=()=>openModal('contact');$('#addTrainingBtn').onclick=()=>openModal('training');$('#modalClose').onclick=$('#cancelBtn').onclick=()=>modal.classList.remove('open');$('#themeBtn').onclick=()=>{document.body.classList.toggle('dark');localStorage.setItem('hrbp-theme',document.body.classList.contains('dark')?'dark':'light')};if(localStorage.getItem('hrbp-theme')==='dark')document.body.classList.add('dark');render();
