(()=>{const btn=document.querySelector('#catMascot');if(!btn)return;let ctx;const meow=()=>{try{ctx??=new (window.AudioContext||window.webkitAudioContext)();if(ctx.state==='suspended')ctx.resume();const now=ctx.currentTime,dur=.72,master=ctx.createGain();master.gain.setValueAtTime(.0001,now);master.gain.exponentialRampToValueAtTime(.22,now+.045);master.gain.exponentialRampToValueAtTime(.0001,now+dur);master.connect(ctx.destination);const voice=ctx.createOscillator(),harm=ctx.createOscillator(),vib=ctx.createOscillator(),vibGain=ctx.createGain(),form1=ctx.createBiquadFilter(),form2=ctx.createBiquadFilter(),voiceGain=ctx.createGain();voice.type='sawtooth';harm.type='triangle';voice.frequency.setValueAtTime(330,now);voice.frequency.exponentialRampToValueAtTime(650,now+.16);voice.frequency.exponentialRampToValueAtTime(245,now+dur);harm.frequency.setValueAtTime(660,now);harm.frequency.exponentialRampToValueAtTime(1300,now+.16);harm.frequency.exponentialRampToValueAtTime(490,now+dur);vib.frequency.value=5.5;vibGain.gain.value=13;vib.connect(vibGain);vibGain.connect(voice.frequency);vibGain.connect(harm.frequency);form1.type='bandpass';form1.frequency.setValueAtTime(720,now);form1.frequency.exponentialRampToValueAtTime(980,now+.17);form1.frequency.exponentialRampToValueAtTime(560,now+dur);form1.Q.value=2.2;form2.type='bandpass';form2.frequency.setValueAtTime(1450,now);form2.frequency.exponentialRampToValueAtTime(2050,now+.17);form2.frequency.exponentialRampToValueAtTime(1050,now+dur);form2.Q.value=3.1;voiceGain.gain.value=.16;voice.connect(form1);voice.connect(form2);harm.connect(form1);harm.connect(form2);form1.connect(voiceGain);form2.connect(voiceGain);voiceGain.connect(master);voice.start(now);harm.start(now);vib.start(now);voice.stop(now+dur);harm.stop(now+dur);vib.stop(now+dur);const puff=ctx.createBufferSource(),buf=ctx.createBuffer(1,ctx.sampleRate*.09,ctx.sampleRate),noise=buf.getChannelData(0);for(let i=0;i<noise.length;i++)noise[i]=(Math.random()*2-1)*Math.pow(1-i/noise.length,2);puff.buffer=buf;const puffGain=ctx.createGain();puffGain.gain.setValueAtTime(.08,now);puffGain.gain.exponentialRampToValueAtTime(.0001,now+.09);puff.connect(puffGain);puffGain.connect(master);puff.start(now)}catch(_){}};btn.addEventListener('click',meow);btn.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();meow()}})})();
// 部署到 Node 后端时，跨设备同步同一个共享工作区；直接双击 HTML 时自动回退本地存储。
(()=>{const base=window.HRBP_API_BASE??'';const endpoint=`${base}/api/workspace`;const headers={'Content-Type':'application/json'};const token=window.HRBP_CONFIG?.apiToken;if(token)headers['X-Workspace-Token']=token;let remoteSnapshot='';let ready=false;const pull=async()=>{try{const res=await fetch(endpoint,{headers});if(!res.ok)return;const body=await res.json();if(body.payload&&typeof body.payload==='object'){const incoming=JSON.stringify(body.payload);if(!ready||incoming!==remoteSnapshot){data=Object.assign(data,body.payload);localStorage.setItem(KEY,JSON.stringify(data));remoteSnapshot=incoming;render()}}else await push();ready=true}catch(_){}};const push=async()=>{try{const payload=JSON.parse(JSON.stringify(data));const res=await fetch(endpoint,{method:'PUT',headers,body:JSON.stringify({payload})});if(res.ok){remoteSnapshot=JSON.stringify(payload);if(!ready)ready=true}}catch(_){}};pull();setInterval(()=>{const current=JSON.stringify(data);if(ready&&current!==remoteSnapshot)push();else if(!ready)pull()},4000)})();
