(()=>{const pad=n=>String(n).padStart(2,'0');const keyOf=d=>`${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;const mondayOf=d=>{const x=new Date(d);x.setHours(0,0,0,0);const day=x.getDay()||7;x.setDate(x.getDate()-day+1);return x};const weekKey=d=>keyOf(mondayOf(d));const shiftWeek=(key,n)=>{const d=new Date(`${key}T00:00:00`);d.setDate(d.getDate()+n*7);return keyOf(d)};const label=key=>{const s=new Date(`${key}T00:00:00`),e=new Date(s);e.setDate(e.getDate()+6);return `${s.getMonth()+1}月${s.getDate()}日 – ${e.getMonth()+1}月${e.getDate()}日`};const current=weekKey(new Date());data.tasks.forEach(t=>{if(!t.week)t.week=current});let activeWeek=localStorage.getItem('hrbp-active-week')||current;const allWeeks=()=>[...new Set([current,activeWeek,...data.tasks.map(t=>t.week).filter(Boolean)])].sort();const setWeek=k=>{activeWeek=k;localStorage.setItem('hrbp-active-week',k);activeDay='全部';renderTasks();renderStats()};const paintWeeks=()=>{const select=$('#weekSelect');if(!select)return;const weeks=allWeeks();if(!weeks.includes(activeWeek))weeks.push(activeWeek);select.innerHTML=weeks.sort().map(w=>`<option value="${w}" ${w===activeWeek?'selected':''}>第 ${weekOfYear(w)} 周 · ${label(w)}</option>`).join('');select.onchange=()=>setWeek(select.value)};const weekOfYear=k=>{const d=new Date(`${k}T00:00:00`),one=new Date(d.getFullYear(),0,1);return Math.ceil((((d-one)/86400000)+one.getDay()+1)/7)};const renderTaskWeek=renderTasks;renderTasks=function(){paintWeeks();const tabs=['全部','周一','周二','周三','周四','周五'];$('#weekTabs').innerHTML=tabs.map(d=>`<button class="day-tab ${activeDay===d?'active':''}" data-day="${d}">${d}</button>`).join('');$('#weekTabs').querySelectorAll('button').forEach(b=>b.onclick=()=>{activeDay=b.dataset.day;renderTasks()});const list=data.tasks.filter(t=>(t.week||current)===activeWeek&&(activeDay==='全部'||t.day===activeDay));$('#taskList').innerHTML=list.length?list.map(t=>`<div class="task-item ${t.done?'done':''}"><button class="check" data-id="${t.id}">${t.done?'✓':''}</button><div><div class="task-name">${esc(t.name)}</div><div class="task-note">${esc(t.note||'暂无备注')}</div></div><span class="task-owner">${esc(t.owner||'未分配')}</span><div class="row-actions"><button class="mini-btn edit-task" data-id="${t.id}">✎</button><button class="mini-btn delete-task" data-id="${t.id}">×</button></div></div>`).join(''):'<div class="empty">这一周还没有任务，点击“添加任务”开始安排吧</div>';$('#taskList').querySelectorAll('.check').forEach(b=>b.onclick=()=>{const t=data.tasks.find(x=>x.id===b.dataset.id);if(t){t.done=!t.done;save();render()}});$('#taskList').querySelectorAll('.delete-task').forEach(b=>b.onclick=()=>{data.tasks=data.tasks.filter(x=>x.id!==b.dataset.id);save();render()});$('#taskList').querySelectorAll('.edit-task').forEach(b=>b.onclick=()=>openModal('task',data.tasks.find(x=>x.id===b.dataset.id)))};renderStats=function(){const tasks=data.tasks.filter(t=>(t.week||current)===activeWeek),done=tasks.filter(t=>t.done).length,total=tasks.length,people=data.training.reduce((a,r)=>a+Number(r.people),0),intern=data.training.reduce((a,r)=>a+Number(r.intern),0);$('#heroProgress').textContent=Math.round(done/Math.max(total,1)*100)+'%';$('#stats').innerHTML=[['本周任务',`${done}/${total}`,'已完成任务','✓','violet'],['候选人',data.candidates.length,'在招岗位候选人','◎','green'],['培训参与',people,'累计参与人次','▤','orange'],['实习生',intern,'培训实习生人次','↗','pink']].map(x=>`<div class="stat-card"><div class="stat-label">${x[2]}<span class="stat-icon ${x[4]}">${x[3]}</span></div><div class="stat-value">${x[1]}</div><div class="stat-note">${x[0]}</div></div>`).join('')};const oldOpen=openModal;openModal=function(type,it){oldOpen(type,it);if(type==='task'){const fields=$('#modalFields'),existing=fields.querySelector('[name="week"]');if(!existing){fields.insertAdjacentHTML('afterbegin',`<div class="field"><label>所属周</label><select name="week">${allWeeks().sort().map(w=>`<option value="${w}" ${(it?.week||activeWeek)===w?'selected':''}>第 ${weekOfYear(w)} 周 · ${label(w)}</option>`).join('')}</select></div>`)} }};const oldSubmit=$('#modalForm').onsubmit;$('#modalForm').onsubmit=e=>{if(modal.dataset.type==='task'){const week=e.target.querySelector('[name="week"]')?.value||activeWeek;if(!e.target.querySelector('[name="week"]'))return oldSubmit(e);const before=modal.dataset.id?data.tasks.find(t=>t.id===modal.dataset.id):null;oldSubmit(e);if(before)before.week=week;else{const added=data.tasks[data.tasks.length-1];if(added)added.week=week}save();return}return oldSubmit(e)};$('#prevWeekBtn').onclick=()=>setWeek(shiftWeek(activeWeek,-1));$('#nextWeekBtn').onclick=()=>setWeek(shiftWeek(activeWeek,1));$('#weekPrev').onclick=()=>setWeek(shiftWeek(activeWeek,-1));$('#weekNext').onclick=()=>setWeek(shiftWeek(activeWeek,1));$('#weekToday').onclick=()=>setWeek(current);paintWeeks();renderTasks();renderStats()})();
(()=>{const mondayKey=d=>{const x=new Date(d),day=x.getDay()||7;x.setDate(x.getDate()-day+1);return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`};const week=mondayKey(new Date());const dayNames=['周日','周一','周二','周三','周四','周五','周六'];const tasks=data.tasks.filter(t=>(t.week||week)===week);const genDaily=()=>{const now=new Date(),today=dayNames[now.getDay()],tomorrow=dayNames[(now.getDay()+1)%7],todayTasks=tasks.filter(t=>t.day===today),tomorrowTasks=tasks.filter(t=>t.day===tomorrow),done=todayTasks.filter(t=>t.done),pending=todayTasks.filter(t=>!t.done),doneText=done.length?done.map(t=>t.name).join('、'):'暂无已完成任务',pendingText=pending.length?pending.map(t=>t.name).join('、'):'今日任务已全部完成',plan=tomorrowTasks.length?tomorrowTasks.map(t=>t.name).join('、'):'跟进候选人进展并更新工作台';upsertGeneratedSummary({kind:'daily',date:localDateKey(now),weekday:today,title:`${today}工作总结 · ${localDateKey(now)}`,content:`今日完成：${doneText}。\n\n今日任务共 ${todayTasks.length} 项，其中 ${done.length} 项已完成。\n\n待推进：${pendingText}。`,next:`明日（${tomorrow}）计划：${plan}。`})};const genWeekly=()=>{const done=tasks.filter(t=>t.done),pending=tasks.filter(t=>!t.done),roleText=[...new Set(data.candidates.map(c=>c.role))].map(role=>`${role} ${data.candidates.filter(c=>c.role===role).length}人`).join('、')||'暂无候选人';upsertGeneratedSummary({kind:'weekly',date:localDateKey(new Date()),weekday:'周五',title:`本周工作总结 · ${week} 起`,content:`本周完成：完成 ${done.length} 项任务，共 ${tasks.length} 项。\n\n招聘进展：当前看板共 ${data.candidates.length} 位候选人，按岗位分布为 ${roleText}。\n\n培训与协作：本周记录 ${data.training.length} 场培训。`,next:`下周计划：${pending.slice(0,5).map(t=>t.name).join('、')||'持续跟进招聘候选人、完善培训资料与数据统计'}。`})};$('#generateDailyBtn').onclick=genDaily;$('#generateWeeklyBtn').onclick=genWeekly})();
// 生成总结时实时读取当前周任务，避免新增任务后仍使用旧快照。
(()=>{const mondayKey=d=>{const x=new Date(d),day=x.getDay()||7;x.setDate(x.getDate()-day+1);return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`};const week=mondayKey(new Date()),days=['周日','周一','周二','周三','周四','周五','周六'];const currentTasks=()=>data.tasks.filter(t=>(t.week||week)===week);$('#generateDailyBtn').onclick=()=>{const now=new Date(),today=days[now.getDay()],tomorrow=days[(now.getDay()+1)%7],tasks=currentTasks(),todayTasks=tasks.filter(t=>t.day===today),tomorrowTasks=tasks.filter(t=>t.day===tomorrow),done=todayTasks.filter(t=>t.done),pending=todayTasks.filter(t=>!t.done);upsertGeneratedSummary({kind:'daily',date:localDateKey(now),weekday:today,title:`${today}工作总结 · ${localDateKey(now)}`,content:`今日完成：${done.map(t=>t.name).join('、')||'暂无已完成任务'}。\n\n今日任务共 ${todayTasks.length} 项，其中 ${done.length} 项已完成。\n\n待推进：${pending.map(t=>t.name).join('、')||'今日任务已全部完成'}。`,next:`明日（${tomorrow}）计划：${tomorrowTasks.map(t=>t.name).join('、')||'跟进候选人进展并更新工作台'}。`})};$('#generateWeeklyBtn').onclick=()=>{const tasks=currentTasks(),done=tasks.filter(t=>t.done),pending=tasks.filter(t=>!t.done),roles=[...new Set(data.candidates.map(c=>c.role))],roleText=roles.map(role=>`${role} ${data.candidates.filter(c=>c.role===role).length}人`).join('、')||'暂无候选人';upsertGeneratedSummary({kind:'weekly',date:localDateKey(new Date()),weekday:'周五',title:`本周工作总结 · ${week} 起`,content:`本周完成：完成 ${done.length} 项任务，共 ${tasks.length} 项。\n\n招聘进展：当前看板共 ${data.candidates.length} 位候选人，按岗位分布为 ${roleText}。\n\n培训与协作：本周记录 ${data.training.length} 场培训。`,next:`下周计划：${pending.slice(0,5).map(t=>t.name).join('、')||'持续跟进招聘候选人、完善培训资料与数据统计'}。`})}})();

// 招聘数据中心：每日登记是唯一数据源，汇总、渠道、部门和图表均由其自动计算。
(()=>{
  data.recruitRecords=Array.isArray(data.recruitRecords)?data.recruitRecords:[];
  titles.recruit=['TALENT INTELLIGENCE','招聘数据中心','登记一次，汇总、渠道、部门与入职趋势自动联动。'];
  let activeRecruitTab=localStorage.getItem('hrbp-recruit-tab')||'pipeline';
  const firstDone=r=>['通过','未通过'].includes(r.firstStatus);
  const secondDone=r=>['通过','未通过'].includes(r.secondStatus);
  const count=(rows,test)=>rows.filter(test).length;
  const rate=(a,b)=>b?`${Math.round(a/b*100)}%`:'0%';
  const today=()=>{const d=new Date(),p=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}`};
  const unique=values=>[...new Set(values.filter(Boolean))].sort((a,b)=>String(a).localeCompare(String(b),'zh-CN'));
  const emptyRow=(cols,text='暂无数据，先新增一条面试登记吧')=>`<tr><td colspan="${cols}" class="empty">${text}</td></tr>`;
  const statusClass=value=>value==='通过'?'pass':value==='未通过'?'fail':value==='已发'?'yes':value==='已到岗'?'onboard':value==='是'?'yes':value==='否'?'no':'pending';
  const pill=value=>`<span class="status-pill ${statusClass(value)}">${esc(value||'待处理')}</span>`;
  const aggregate=key=>{
    const map=new Map();
    data.recruitRecords.forEach(r=>{const name=r[key]||'未填写';if(!map.has(name))map.set(name,[]);map.get(name).push(r)});
    return [...map].map(([name,rows])=>({name,rows})).sort((a,b)=>b.rows.length-a.rows.length);
  };
  const metrics=rows=>{const invited=count(rows,r=>r.invited),firstPass=count(rows,r=>r.firstStatus==='通过'),firstTotal=count(rows,firstDone),secondPass=count(rows,r=>r.secondStatus==='通过'),secondTotal=count(rows,secondDone),offers=count(rows,r=>r.offerStatus==='已发'),onboard=count(rows,r=>r.onboardStatus==='已到岗');return {records:rows.length,invited,firstPass,firstTotal,secondPass,secondTotal,offers,onboard,firstRate:rate(firstPass,firstTotal),secondRate:rate(secondPass,secondTotal),onboardRate:rate(onboard,offers)}};

  function ensureRecordModal(){
    if($('#recruitRecordModal'))return;
    document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop recruit-record-modal" id="recruitRecordModal"><div class="modal"><div class="modal-head"><h3 id="recruitRecordModalTitle">新增面试登记</h3><button class="close-btn" type="button" data-record-close>×</button></div><form id="recruitRecordForm"><div id="recruitRecordFields"></div><div class="modal-actions"><button type="button" class="ghost-btn" data-record-close>取消</button><button class="primary-btn" type="submit">保存登记</button></div></form></div></div>`);
    $('#recruitRecordModal').querySelectorAll('[data-record-close]').forEach(b=>b.onclick=()=>$('#recruitRecordModal').classList.remove('open'));
    $('#recruitRecordModal').onclick=e=>{if(e.target.id==='recruitRecordModal')e.currentTarget.classList.remove('open')};
    $('#recruitRecordForm').onsubmit=submitRecord;
  }

  function recordFields(r={}){
    const option=(values,current)=>values.map(v=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(v)}</option>`).join('');
    return `<p class="form-note">带 * 的字段用于所有自动公式与仪表盘，请尽量完整填写。</p>
      <div class="field-row"><div class="field"><label>面试日期 *</label><input type="date" name="date" required value="${esc(r.date||today())}"></div><div class="field"><label>候选人姓名 *</label><input name="name" required value="${esc(r.name)}" placeholder="例如：李晓雨"></div></div>
      <div class="field-row"><div class="field"><label>手机号 / 联系方式</label><input name="contact" value="${esc(r.contact)}" placeholder="选填"></div><div class="field"><label>招聘负责人</label><input name="owner" value="${esc(r.owner||'Maggie')}"></div></div>
      <div class="field-row"><div class="field"><label>应聘部门 *</label><input name="department" required value="${esc(r.department)}" list="recruitDepartmentList" placeholder="例如：教研部"></div><div class="field"><label>应聘岗位 *</label><input name="role" required value="${esc(r.role)}" placeholder="例如：英语教研实习生"></div></div>
      <datalist id="recruitDepartmentList">${unique(data.recruitRecords.map(x=>x.department)).map(v=>`<option value="${esc(v)}">`).join('')}</datalist>
      <div class="field-row"><div class="field"><label>简历来源 *</label><input name="source" required value="${esc(r.source)}" list="recruitSourceList" placeholder="例如：Boss / 内推 / 校招"></div><div class="field"><label>到岗日期</label><input type="date" name="onboardDate" value="${esc(r.onboardDate)}"></div></div>
      <datalist id="recruitSourceList">${unique(data.recruitRecords.map(x=>x.source)).map(v=>`<option value="${esc(v)}">`).join('')}</datalist>
      <div class="field-row"><div class="field"><label>是否已邀约</label><div class="toggle-field"><input type="checkbox" id="recordInvited" name="invited" ${r.invited?'checked':''}><label for="recordInvited">计入邀约人数</label></div></div><div class="field"><label>初试结果</label><select name="firstStatus">${option(['待面试','通过','未通过'],r.firstStatus||'待面试')}</select></div></div>
      <div class="field-row"><div class="field"><label>复试结果</label><select name="secondStatus">${option(['无需复试','待面试','通过','未通过'],r.secondStatus||'待面试')}</select></div><div class="field"><label>Offer 状态</label><select name="offerStatus">${option(['未发','待审批','已发'],r.offerStatus||'未发')}</select></div></div>
      <div class="field-row"><div class="field"><label>到岗状态</label><select name="onboardStatus">${option(['未到岗','待到岗','已到岗'],r.onboardStatus||'未到岗')}</select></div><div class="field"><label>备注</label><input name="note" value="${esc(r.note)}" placeholder="进度、反馈或后续动作"></div></div>`;
  }

  function openRecordModal(record){
    ensureRecordModal();
    const modal=$('#recruitRecordModal');modal.dataset.id=record?.id||'';
    $('#recruitRecordModalTitle').textContent=record?'编辑面试登记':'新增面试登记';
    $('#recruitRecordFields').innerHTML=recordFields(record);
    modal.classList.add('open');
  }

  function submitRecord(e){
    e.preventDefault();const modal=$('#recruitRecordModal'),id=modal.dataset.id,o=Object.fromEntries(new FormData(e.target).entries());
    const clean={...o,invited:e.target.elements.invited.checked};
    if(clean.onboardStatus!=='已到岗')clean.onboardDate='';
    if(id){const old=data.recruitRecords.find(r=>r.id===id);if(old)Object.assign(old,clean)}else data.recruitRecords.unshift({...clean,id:uid('rr')});
    modal.classList.remove('open');save();render();
  }

  function setRecruitTab(name){
    activeRecruitTab=name;localStorage.setItem('hrbp-recruit-tab',name);
    document.querySelectorAll('[data-recruit-tab]').forEach(b=>b.classList.toggle('active',b.dataset.recruitTab===name));
    document.querySelectorAll('[data-recruit-pane]').forEach(p=>p.classList.toggle('active',p.dataset.recruitPane===name));
    const pipeline=name==='pipeline';$('#manageStageBtn').style.display=pipeline?'':'none';$('#addCandidateBtn').style.display=pipeline?'':'none';
    if(name!=='pipeline')renderRecruitmentData();
  }

  function renderKpis(){
    const m=metrics(data.recruitRecords);
    $('#recruitKpis').innerHTML=[['登记候选人',m.records,'全部面试记录'],['邀约人数',m.invited,rate(m.invited,m.records)+' 邀约率'],['初试通过率',m.firstRate,`${m.firstPass}/${m.firstTotal} 人`],['复试通过率',m.secondRate,`${m.secondPass}/${m.secondTotal} 人`],['到岗率',m.onboardRate,`${m.onboard}/${m.offers} 人`]].map(x=>`<article class="recruit-kpi"><span>${x[0]}</span><strong>${x[1]}</strong><small>${x[2]}</small></article>`).join('');
  }

  function renderDepartmentChart(){
    const groups=aggregate('department').slice(0,8),el=$('#departmentBarChart');if(!groups.length){el.innerHTML='<div class="chart-empty">暂无部门数据<br>新增面试登记后自动生成柱状图</div>';return}
    const top=Math.max(...groups.map(g=>g.rows.length),1);
    el.innerHTML=`<div class="department-bars">${groups.map(g=>{const onboard=count(g.rows,r=>r.onboardStatus==='已到岗');return `<div class="department-bar-item" title="${esc(g.name)}：${g.rows.length} 位候选人，${onboard} 人到岗"><div class="bar-pair"><i class="bar-candidate" style="height:${Math.max(3,g.rows.length/top*100)}%"></i><i class="bar-onboard" style="height:${Math.max(onboard?3:0,onboard/top*100)}%"></i></div><small>${esc(g.name)}</small></div>`}).join('')}</div><div class="chart-legend"><span><i class="candidate"></i>候选人数</span><span><i class="onboard"></i>已到岗</span></div>`;
  }

  function renderSourceChart(){
    const groups=aggregate('source'),el=$('#sourceDonutChart');if(!groups.length){el.innerHTML='<div class="chart-empty">暂无渠道数据<br>登记简历来源后自动生成环形图</div>';return}
    const colors=['#6ba9dc','#e88da5','#71bfa6','#edae72','#9d83c8','#7ec7d3','#d7a678','#a3c97d'],total=data.recruitRecords.length;let cursor=0;
    const stops=groups.map((g,i)=>{const from=cursor;cursor+=g.rows.length/total*100;return `${colors[i%colors.length]} ${from}% ${cursor}%`}).join(',');
    el.innerHTML=`<div class="source-donut-layout"><div class="source-donut" style="background:conic-gradient(${stops})"><div class="source-donut-center"><strong>${total}</strong><small>份简历</small></div></div><div class="source-legend">${groups.map((g,i)=>`<div><i style="background:${colors[i%colors.length]}"></i><span>${esc(g.name)}</span><b>${Math.round(g.rows.length/total*100)}%</b></div>`).join('')}</div></div>`;
  }

  function renderLineChart(){
    const el=$('#onboardLineChart'),rows=data.recruitRecords.filter(r=>r.onboardStatus==='已到岗'&&r.onboardDate);if(!rows.length){el.innerHTML='<div class="chart-empty">暂无入职走势<br>登记“已到岗”和到岗日期后自动生成折线图</div>';return}
    const byMonth=new Map();rows.forEach(r=>{const key=r.onboardDate.slice(0,7);byMonth.set(key,(byMonth.get(key)||0)+1)});const months=[...byMonth.keys()].sort().slice(-12),values=months.map(m=>byMonth.get(m)),max=Math.max(...values,1),w=760,h=190,padX=42,padY=24,step=months.length>1?(w-padX*2)/(months.length-1):0;const pts=values.map((v,i)=>({x:months.length===1?w/2:padX+i*step,y:h-padY-v/max*(h-padY*2),v,label:months[i].replace('-', '/')}));const line=pts.map(p=>`${p.x},${p.y}`).join(' '),area=`${pts[0].x},${h-padY} ${line} ${pts.at(-1).x},${h-padY}`;
    el.innerHTML=`<svg class="line-chart" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" role="img" aria-label="月度入职人数折线图"><defs><linearGradient id="trendFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#9dd5f4" stop-opacity=".45"/><stop offset="1" stop-color="#9dd5f4" stop-opacity="0"/></linearGradient></defs>${[0,.25,.5,.75,1].map(n=>`<line class="grid" x1="${padX}" y1="${padY+n*(h-padY*2)}" x2="${w-padX}" y2="${padY+n*(h-padY*2)}"/>`).join('')}<polygon class="trend-fill" points="${area}"/><polyline class="trend-line" points="${line}"/>${pts.map(p=>`<circle class="trend-dot" cx="${p.x}" cy="${p.y}" r="4"><title>${p.label}：${p.v} 人</title></circle><text class="axis-label" x="${p.x}" y="${h-5}" text-anchor="middle">${p.label}</text><text class="axis-label" x="${p.x}" y="${p.y-10}" text-anchor="middle">${p.v}</text>`).join('')}</svg>`;
  }

  function renderRecordFilters(){
    const dept=$('#recruitDeptFilter'),source=$('#recruitSourceFilter'),oldDept=dept.value,oldSource=source.value;
    dept.innerHTML='<option value="">全部部门</option>'+unique(data.recruitRecords.map(r=>r.department)).map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('');
    source.innerHTML='<option value="">全部来源</option>'+unique(data.recruitRecords.map(r=>r.source)).map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('');dept.value=oldDept;source.value=oldSource;
  }

  function filteredRecords(){const date=$('#recruitDateFilter').value,dept=$('#recruitDeptFilter').value,source=$('#recruitSourceFilter').value,q=$('#recruitSearch').value.trim().toLowerCase();return data.recruitRecords.filter(r=>(!date||r.date===date)&&(!dept||r.department===dept)&&(!source||r.source===source)&&(!q||`${r.name} ${r.role} ${r.contact||''}`.toLowerCase().includes(q)))}

  function renderRecordTable(){
    const rows=filteredRecords().sort((a,b)=>(b.date||'').localeCompare(a.date||''));
    $('#recruitRecordTable').innerHTML=rows.length?rows.map(r=>`<tr><td>${esc(r.date||'-')}</td><td><div class="record-person"><strong>${esc(r.name)}</strong><small>${esc(r.contact||r.owner||'')}</small></div></td><td><div class="record-position"><strong>${esc(r.department)}</strong><small>${esc(r.role)}</small></div></td><td>${esc(r.source||'-')}</td><td>${pill(r.invited?'是':'否')}</td><td>${pill(r.firstStatus)}</td><td>${pill(r.secondStatus)}</td><td>${pill(r.offerStatus)}</td><td>${pill(r.onboardStatus)}</td><td><div class="record-actions"><button class="edit-record" data-id="${r.id}" aria-label="编辑">✎</button><button class="delete-record" data-id="${r.id}" aria-label="删除">×</button></div></td></tr>`).join(''):emptyRow(10,'没有符合筛选条件的面试记录');
    $('#recruitRecordTable').querySelectorAll('.edit-record').forEach(b=>b.onclick=()=>openRecordModal(data.recruitRecords.find(r=>r.id===b.dataset.id)));
    $('#recruitRecordTable').querySelectorAll('.delete-record').forEach(b=>b.onclick=()=>{const r=data.recruitRecords.find(x=>x.id===b.dataset.id);if(confirm(`确定删除 ${r?.name||'这位候选人'} 的面试登记吗？`)){data.recruitRecords=data.recruitRecords.filter(x=>x.id!==b.dataset.id);save();render()}});
  }

  function renderChannelTable(){
    const groups=aggregate('source');$('#channelStatsTable').innerHTML=groups.length?groups.map(g=>{const m=metrics(g.rows);return `<tr><td><strong>${esc(g.name)}</strong></td><td>${m.records}</td><td>${m.invited}</td><td>${m.firstPass}</td><td>${m.secondPass}</td><td>${m.offers}</td><td>${m.onboard}</td><td class="metric-rate">${rate(m.invited,m.records)}</td><td class="metric-rate">${rate(m.onboard,m.records)}</td></tr>`}).join(''):emptyRow(9,'暂无渠道数据');
  }

  function renderDepartmentTable(){
    const groups=aggregate('department');$('#departmentStatsTable').innerHTML=groups.length?groups.map(g=>{const m=metrics(g.rows),roles=unique(g.rows.map(r=>r.role));return `<tr><td><strong>${esc(g.name)}</strong></td><td>${m.records}</td><td>${m.invited}</td><td>${m.firstTotal}</td><td>${m.secondTotal}</td><td>${m.offers}</td><td>${m.onboard}</td><td class="metric-rate">${m.onboardRate}</td><td>${roles.map(esc).join('、')}</td></tr>`}).join(''):emptyRow(9,'暂无部门招录数据');
  }

  function renderRecruitmentData(){
    if(!$('#recruitTabs'))return;renderKpis();renderDepartmentChart();renderSourceChart();renderLineChart();renderRecordFilters();renderRecordTable();renderChannelTable();renderDepartmentTable();setRecruitTabVisualOnly();
  }
  function setRecruitTabVisualOnly(){document.querySelectorAll('[data-recruit-tab]').forEach(b=>b.classList.toggle('active',b.dataset.recruitTab===activeRecruitTab));document.querySelectorAll('[data-recruit-pane]').forEach(p=>p.classList.toggle('active',p.dataset.recruitPane===activeRecruitTab));const pipeline=activeRecruitTab==='pipeline';$('#manageStageBtn').style.display=pipeline?'':'none';$('#addCandidateBtn').style.display=pipeline?'':'none'}

  ensureRecordModal();
  $('#recruitTabs').querySelectorAll('[data-recruit-tab]').forEach(b=>b.onclick=()=>setRecruitTab(b.dataset.recruitTab));
  $('#addRecruitRecordBtn').onclick=()=>openRecordModal();
  ['#recruitDateFilter','#recruitDeptFilter','#recruitSourceFilter'].forEach(s=>$(s).addEventListener('change',renderRecordTable));
  $('#recruitSearch').addEventListener('input',renderRecordTable);
  const baseRender=render;render=function(){baseRender();renderRecruitmentData()};
  renderRecruitmentData();setRecruitTabVisualOnly();
})();
